  /* 2. Rollen: light-dark(hell, dunkel) wählt je nach color-scheme. */
  --text: light-dark(var(--ink-900), var(--ink-100));
  --page: light-dark(var(--page-50), var(--page-950));
  --surface: light-dark(var(--paper-0), var(--paper-900));
  --accent: light-dark(var(--blue-700), var(--blue-300));
  --border: light-dark(var(--line-500), var(--line-400));

  /* Abstände und Radien sind ebenfalls Tokens, damit Komponenten keine Zahlen erfinden. */
  --space-1: 0.5rem;
  --space-2: 1rem;
  --space-3: 1.5rem;
  --radius: 0.5rem;
  --target: 2.75rem;
}

