/* Manuelle Wahl: ein Attribut am Wurzelelement überschreibt die Systemeinstellung. */
:root[data-theme='light'] { color-scheme: light; }
:root[data-theme='dark'] { color-scheme: dark; }

/* 3. Komponenten benutzen nur Rollen und Abstände. */
body { margin: 0; padding: var(--space-3); background: var(--page); color: var(--text); font: 1rem/1.6 system-ui, sans-serif; }
a { color: var(--accent); text-underline-offset: 0.2em; }
.card { background: var(--surface); border: 1px solid var(--border); border-radius: var(--radius); padding: var(--space-2); }
.button { min-height: var(--target); padding: 0 var(--space-2); border: 1px solid var(--accent); border-radius: var(--radius); background: var(--accent); color: var(--surface); font: inherit; font-weight: 600; }
.button:focus-visible, a:focus-visible { outline: 3px solid var(--accent); outline-offset: 3px; }

