/* Ruhiger Standard: kein Übergang, kein Ruckeln. Bewegung gibt es nur, wenn die Person sie nicht abgewählt hat. */
@media (prefers-reduced-motion: no-preference) {
  .panel { transition: transform 200ms ease-out, opacity 200ms ease-out; }
  .panel[data-aus] { opacity: 0; transform: translateY(0.5rem); }
  .lade { animation: drehen 1s linear infinite; }
}

/* Nur transform und opacity werden animiert: Sie laufen ohne neues Layout auf der Grafikkarte. */
@keyframes drehen { to { transform: rotate(360deg); } }

